import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"CodeBuddy Glossary","description":"No how-to. Name collisions in the CodeBuddy family: three coding surfaces, WorkBuddy, Hunyuan, CN vs intl sites, CODEBUDDY.md.","frontmatter":{"title":"CodeBuddy Glossary","description":"No how-to. Name collisions in the CodeBuddy family: three coding surfaces, WorkBuddy, Hunyuan, CN vs intl sites, CODEBUDDY.md.","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"products/codebuddy/codebuddy-glossary.md","filePath":"products/codebuddy/codebuddy-glossary.md","lastUpdated":1787110548000}'),d={name:"products/codebuddy/codebuddy-glossary.md"};function s(i,e,r,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="codebuddy-glossary" tabindex="-1">CodeBuddy Glossary <a class="header-anchor" href="#codebuddy-glossary" aria-label="Permalink to &quot;CodeBuddy Glossary&quot;">​</a></h1><p>No how-to. This page answers &quot;what is it / what is it not&quot;. Pick a surface on the <a href="./">map</a>.</p><h2 id="concept-map" tabindex="-1">Concept map <a class="header-anchor" href="#concept-map" aria-label="Permalink to &quot;Concept map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tencent AI (the slice this directory cares about)</span></span>
<span class="line"><span>├── CodeBuddy — coding family</span></span>
<span class="line"><span>│   ├── IDE</span></span>
<span class="line"><span>│   ├── Plugin (VS Code / JetBrains / …)</span></span>
<span class="line"><span>│   └── CodeBuddy Code (CLI, command codebuddy)</span></span>
<span class="line"><span>│       ├── Interactive REPL</span></span>
<span class="line"><span>│       ├── Print (-p)</span></span>
<span class="line"><span>│       └── CLI-native plugin / Skills / MCP</span></span>
<span class="line"><span>├── WorkBuddy — office workbench (not the coding path)</span></span>
<span class="line"><span>├── Yuanbao — general assistant</span></span>
<span class="line"><span>└── Hunyuan — model (one engine CodeBuddy can switch to)</span></span></code></pre></div><h2 id="codebuddy" tabindex="-1">CodeBuddy <a class="header-anchor" href="#codebuddy" aria-label="Permalink to &quot;CodeBuddy&quot;">​</a></h2><p><strong>What it is</strong>: Tencent Cloud&#39;s AI coding assistant. Official definition (<a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">docs overview</a>, <a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">product overview</a>): <strong>IDE, plugin, and CLI</strong>.</p><p><strong>What it is not</strong>: not Hunyuan itself, not Yuanbao, not WorkBuddy. Marketing copy says it is based on Hunyuan code models; the same official docs also mention DeepSeek and other chat models.</p><p>The three coding forms share one account quota (<a href="https://www.codebuddy.cn/docs/cli/troubleshooting" target="_blank" rel="noreferrer">troubleshooting</a>).</p><h2 id="codebuddy-ide" tabindex="-1">CodeBuddy IDE <a class="header-anchor" href="#codebuddy-ide" aria-label="Permalink to &quot;CodeBuddy IDE&quot;">​</a></h2><p><strong>What it is</strong>: a standalone editor. Official pitch: a product-design-dev workbench; &quot;conversation is programming&quot;. Audience: PMs / designers / full-stack / beginners.</p><p><strong>Why it exists</strong>: the plugin assists inside an IDE you already have; the IDE keeps requirements, design, code, and deploy in one product.</p><p><strong>What it is not</strong>: not a reskin of the VS Code extension. Requirements: macOS 11+ / Windows 10+ (<a href="https://www.codebuddy.cn/docs/ide/Getting-Started/Installation" target="_blank" rel="noreferrer">install</a>).</p><h2 id="codebuddy-plugin" tabindex="-1">CodeBuddy Plugin <a class="header-anchor" href="#codebuddy-plugin" aria-label="Permalink to &quot;CodeBuddy Plugin&quot;">​</a></h2><p><strong>What it is</strong>: an extension for an existing editor. Official marketplace name: <strong>腾讯云代码助手</strong>. Hosts include VS Code, Visual Studio, JetBrains family, Android Studio, and WeChat DevTools (<a href="https://www.codebuddy.cn/docs/plugin/" target="_blank" rel="noreferrer">plugin page</a>).</p><p><strong>Why it exists</strong>: you already have an editor and a workflow; you want completion, chat, and repo Q&amp;A.</p><p><strong>What it is not</strong>:</p><ul><li>not <code>codebuddy plugin</code> on the CLI</li><li>listing WeChat DevTools as a host is not a WeChat or QQ product tutorial</li></ul><h2 id="codebuddy-code" tabindex="-1">CodeBuddy Code <a class="header-anchor" href="#codebuddy-code" aria-label="Permalink to &quot;CodeBuddy Code&quot;">​</a></h2><p><strong>What it is</strong>: an AI CLI for professional engineers. Binary <code>codebuddy</code>, npm package <code>@tencent-ai/codebuddy-code</code>. Official audience: DevOps / SRE / senior engineers.</p><p><strong>Three faces</strong> (one product):</p><table tabindex="0"><thead><tr><th>Face</th><th>Entry</th></tr></thead><tbody><tr><td>Interactive REPL</td><td><code>codebuddy</code></td></tr><tr><td>Print / headless</td><td><code>codebuddy -p &quot;...&quot;</code></td></tr><tr><td>Hosted extras</td><td><code>codebuddy --serve</code>, <code>daemon</code>, <code>--bg</code></td></tr></tbody></table><p><strong>What it is not</strong>: not a retired &quot;Tencent Copilot&quot; product name. The CN login host is <code>copilot.tencent.com</code>; that is an auth site, not a second product.</p><h2 id="workbuddy" tabindex="-1">WorkBuddy <a class="header-anchor" href="#workbuddy" aria-label="Permalink to &quot;WorkBuddy&quot;">​</a></h2><p><strong>What it is</strong>: official wording (<a href="https://www.codebuddy.cn/docs/workbuddy/" target="_blank" rel="noreferrer">WorkBuddy intro</a>) — &quot;WorkBuddy is Tencent&#39;s all-scenario AI office workbench.&quot; The docs nav lists it next to CodeBuddy IDE / plugin / CLI.</p><p><strong>Why it is on this table</strong>: family completeness forbids dropping a first-level entry. Issue #78 only ships the three coding forms, so WorkBuddy stays one row.</p><p><strong>What it is not</strong>: not &quot;CodeBuddy IDE on a phone&quot;. The mini program and the App belong to WorkBuddy.</p><h2 id="yuanbao" tabindex="-1">Yuanbao <a class="header-anchor" href="#yuanbao" aria-label="Permalink to &quot;Yuanbao&quot;">​</a></h2><p><strong>What it is</strong>: Tencent&#39;s general AI assistant. <a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a>.</p><p><strong>What it is not</strong>: not CodeBuddy. No tutorial here (issue #76).</p><h2 id="hunyuan" tabindex="-1">Hunyuan <a class="header-anchor" href="#hunyuan" aria-label="Permalink to &quot;Hunyuan&quot;">​</a></h2><p><strong>What it is</strong>: Tencent&#39;s model family. <a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a>, <a href="https://cloud.tencent.com/product/tclm" target="_blank" rel="noreferrer">cloud tclm</a>. CodeBuddy official copy: Hunyuan, DeepSeek, and other chat models.</p><p><strong>What it is not</strong>: not a coding IDE, and not something you <code>npm install</code>. No Hunyuan API tutorial here (issue #77).</p><h2 id="cn-vs-intl-sites" tabindex="-1">CN vs intl sites <a class="header-anchor" href="#cn-vs-intl-sites" aria-label="Permalink to &quot;CN vs intl sites&quot;">​</a></h2><p><strong>What they are</strong>: two sites and two login domains.</p><table tabindex="0"><thead><tr><th></th><th>China</th><th>International</th></tr></thead><tbody><tr><td>Docs / marketing</td><td>codebuddy.cn</td><td>codebuddy.ai</td></tr><tr><td>CLI login option</td><td>Chinese Site → copilot.tencent.com</td><td>International Site → codebuddy.ai</td></tr><tr><td>IDE download (official table)</td><td><a href="https://copilot.tencent.com/ide" target="_blank" rel="noreferrer">copilot.tencent.com/ide</a></td><td><a href="https://www.codebuddy.ai/" target="_blank" rel="noreferrer">codebuddy.ai</a></td></tr></tbody></table><p><strong>Why it matters</strong>: model lists and auth domains differ. The official quick start says the China site supports mainstream CN models and the intl site supports mainstream overseas models.</p><p><strong>What they are not</strong>: not &quot;one site is stale&quot;. Both update. If an English overview omits the plugin form, follow the ZH overview and Tencent Cloud 1831 docs.</p><h2 id="enterprise" tabindex="-1">Enterprise <a class="header-anchor" href="#enterprise" aria-label="Permalink to &quot;Enterprise&quot;">​</a></h2><p><strong>What it is</strong>: SaaS flagship and dedicated private-cloud editions. Sign-in goes through Tencent Unified Identity or an address from your admin.</p><p><strong>What it is not</strong>: not a reskin of the personal plan. Purchase is out of this tutorial.</p><h2 id="codebuddy-md" tabindex="-1"><code>CODEBUDDY.md</code> <a class="header-anchor" href="#codebuddy-md" aria-label="Permalink to &quot;\`CODEBUDDY.md\`&quot;">​</a></h2><p><strong>What it is</strong>: the official counterpart of <code>CLAUDE.md</code> when migrating from Claude Code — &quot;AI instructions and memory&quot;. The user-level path in the sample is <code>~/.codebuddy/CODEBUDDY.md</code>.</p><p><strong>Why it exists</strong>: standing rules should not be retyped every session.</p><p><strong>What it is not</strong>: not the CLI plugin list, and not the Skills directory. Skills live in <code>~/.codebuddy/skills/</code>; custom slash commands live in <code>.codebuddy/commands/</code>.</p><p>Whether a repo-root <code>CODEBUDDY.md</code> is auto-read is not a hard sentence on the troubleshooting page. Check <code>/config</code> and the official memory doc.</p><h2 id="permission-modes" tabindex="-1">Permission modes <a class="header-anchor" href="#permission-modes" aria-label="Permalink to &quot;Permission modes&quot;">​</a></h2><p><strong>What they are</strong>: CLI knobs for &quot;ask me before this tool call&quot;. Official <code>--permission-mode</code> values: <code>default</code>, <code>acceptEdits</code>, <code>auto</code>, <code>dontAsk</code>, <code>plan</code>, <code>bypassPermissions</code>. The <code>Shift+Tab</code> cycle is written <code>default → bypass → accept → plan</code>.</p><p><strong>Why two namings</strong>: the key hint uses short names; scripts should use the flag names.</p><p><strong>What they are not</strong>: not the sandbox. <code>--sandbox</code> (official Beta) limits filesystem / network after a call is approved.</p><h2 id="cli-plugin-vs-editor-plugin" tabindex="-1">CLI plugin vs editor plugin <a class="header-anchor" href="#cli-plugin-vs-editor-plugin" aria-label="Permalink to &quot;CLI plugin vs editor plugin&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Editor plugin</th><th>CLI plugin</th></tr></thead><tbody><tr><td>Lives in</td><td>VS Code / JetBrains…</td><td><code>codebuddy plugin install</code></td></tr><tr><td>Docs tree</td><td><code>/docs/plugin/</code></td><td><code>/docs/cli/</code> plugin system / marketplace</td></tr><tr><td>Job</td><td>Completion and chat in an existing IDE</td><td>Package Skills / hooks / tools for the terminal agent</td></tr></tbody></table><p>Same English word, two installs.</p><h2 id="do-not-write-these-as-facts" tabindex="-1">Do not write these as facts <a class="header-anchor" href="#do-not-write-these-as-facts" aria-label="Permalink to &quot;Do not write these as facts&quot;">​</a></h2><ul><li>&quot;CodeBuddy is only a plugin&quot; — official first-level nav has three coding forms</li><li>&quot;CodeBuddy is the Hunyuan IDE&quot; — Hunyuan is a model</li><li>A <code>gh</code>-style Tencent Copilot extension as the current CLI — the shipping package is <code>@tencent-ai/codebuddy-code</code></li><li>WorkBuddy as a CodeBuddy mode</li></ul>`,54)])])}const b=t(d,[["render",s]]);export{m as __pageData,b as default};
